51	fn check_version(tsc_path: &Utf8Path, expected: &'static [&'static str]) -> Result<(), TscClientError> {
52	    let reason_at = |reason: String| TscClientError::VersionCheckFailed { path: tsc_path.to_owned(), reason };
53	
54	    let Some(package_json) =
55	        tsc_path.parent().and_then(|bin_dir| bin_dir.parent()).map(|pkg_dir| pkg_dir.join("package.json"))
56	    else {
57	        return Err(reason_at("tsc_path has no grandparent directory to find package.json in".to_string()));
58	    };
59	
60	    let contents = std::fs::read_to_string(&package_json)
61	        .map_err(|source| reason_at(format!("reading {package_json}: {source}")))?;
62	    let value: serde_json::Value =
63	        serde_json::from_str(&contents).map_err(|source| reason_at(format!("parsing {package_json}: {source}")))?;
64	    let Some(found) = value.get("version").and_then(|v| v.as_str()) else {
65	        return Err(reason_at(format!("{package_json} has no \"version\" string")));
66	    };
67	
68	    if expected.contains(&found) {
69	        Ok(())
70	    } else {
71	        Err(TscClientError::UnsupportedVersion { path: tsc_path.to_owned(), found: found.to_string(), expected })
72	    }
73	}
