75	fn spawn_stderr_drain(stderr: tokio::process::ChildStderr) {
76	    // Must be continuously drained: an unread stderr pipe fills its OS buffer and can
77	    // deadlock the child. Logged at debug, not warn — tsc's own diagnostic chatter
78	    // isn't inherently an error, but it's valuable when a crash needs explaining.
79	    tokio::spawn(async move {
80	        let mut lines = tokio::io::BufReader::new(stderr).lines();
81	        while let Ok(Some(line)) = lines.next_line().await {
82	            tracing::debug!(target: "tsc_client::stderr", "{line}");
83	        }
84	    });
85	}
