use tokio::io::AsyncWriteExt;
use tokio_stream::StreamExt;
use tokio_util::codec::FramedRead;

type Requests = FramedRead<tokio::io::Stdin, ContentLengthDecoder>;

fn requests() -> Requests {
    FramedRead::new(tokio::io::stdin(), ContentLengthDecoder::new(DEFAULT_MAX_FRAME_BYTES))
}

#[tokio::main]
async fn main() {
    let scenario = std::env::var("FAKE_TSC_SCENARIO").unwrap_or_else(|_| "echo".to_string());
    let mut parts = scenario.splitn(3, ':');
    let name = parts.next().unwrap_or("echo");
    let arg1 = parts.next();
    let arg2 = parts.next();

    match name {
        "never_respond" => never_respond().await,
        "hang_after_n" => hang_after_n(arg1.and_then(|s| s.parse().ok()).unwrap_or(0)).await,
        "exit_after" => {
            exit_after(arg1.and_then(|s| s.parse().ok()).unwrap_or(0), arg2.and_then(|s| s.parse().ok()).unwrap_or(1))
                .await;
        }
        "crash_immediately" => std::process::exit(arg1.and_then(|s| s.parse().ok()).unwrap_or(1)),
        "garbage_bytes" => garbage_bytes().await,
        "bad_content_length" => bad_content_length().await,
        "oversized_frame" => oversized_frame(arg1.and_then(|s| s.parse().ok()).unwrap_or(usize::MAX)).await,
        "truncated_body" => truncated_body().await,
        "reorder_ack" => reorder_ack().await,
        "shutdown_slow" => shutdown_slow(arg1.and_then(|s| s.parse().ok()).unwrap_or(10_000)).await,
        _ => echo().await,
    }
}

fn request_id(request: &serde_json::Value) -> serde_json::Value {
    request.get("id").cloned().unwrap_or(serde_json::Value::Null)
}

async fn read_request(reader: &mut Requests) -> Option<serde_json::Value> {
    match reader.next().await {
        Some(Ok(body)) => serde_json::from_slice(&body).ok(),
        _ => None,
    }
}

async fn respond<W: tokio::io::AsyncWrite + Unpin>(writer: &mut W, id: &serde_json::Value, result: serde_json::Value) {
    let body = serde_json::json!({ "id": id, "result": result });
    if let Ok(bytes) = serde_json::to_vec(&body) {
        let _ = write_frame(writer, &bytes).await;
    }
}

async fn respond_error<W: tokio::io::AsyncWrite + Unpin>(
    writer: &mut W,
    id: &serde_json::Value,
    code: i64,
    message: &str,
) {
    let body = serde_json::json!({ "id": id, "error": { "code": code, "message": message } });
    if let Ok(bytes) = serde_json::to_vec(&body) {
        let _ = write_frame(writer, &bytes).await;
    }
}

mod common;

use std::time::Duration;

use oxc_react_docgen_tsc_client::{MalformedFrameReason, Supervisor, TscClientError};

async fn expect_malformed(scenario: &str, expected_reason: MalformedFrameReason) {
    let (_dir, config) = common::spawn_fake(scenario);
    let mut supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");

    match supervisor.request("ping", serde_json::json!({}), Duration::from_secs(2)).await {
        Err(TscClientError::MalformedFrame { reason }) => {
            assert_eq!(reason, expected_reason, "scenario {scenario:?}")
        }
        Err(other) => panic!("scenario {scenario:?}: expected MalformedFrame({expected_reason:?}), got {other:?}"),
        Ok(response) => panic!("scenario {scenario:?}: expected an error, got a response: {response:?}"),
    }
}

#[tokio::test]
async fn garbage_bytes_are_reported_as_a_missing_content_length_header() {
    expect_malformed("garbage_bytes", MalformedFrameReason::NoContentLengthHeader).await;
}

#[tokio::test]
async fn an_unparsable_content_length_is_reported_distinctly() {
    expect_malformed("bad_content_length", MalformedFrameReason::UnparsableContentLength).await;
}

#[tokio::test]
async fn a_truncated_body_is_reported_distinctly() {
    expect_malformed("truncated_body", MalformedFrameReason::TruncatedBody).await;
}

#[tokio::test]
async fn an_oversized_declared_length_is_rejected_before_reading_the_body() {
    let (_dir, config) = common::spawn_fake("oversized_frame:100000000"); // 100 MB, well past the 16 MiB cap
    let mut supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");

    match supervisor.request("ping", serde_json::json!({}), Duration::from_secs(2)).await {
        Err(TscClientError::OversizedFrame { declared, cap }) => {
            assert_eq!(declared, 100_000_000);
            assert_eq!(cap, oxc_react_docgen_tsc_client::transport::DEFAULT_MAX_FRAME_BYTES);
        }
        Err(other) => panic!("expected OversizedFrame, got {other:?}"),
        Ok(response) => panic!("expected OversizedFrame, got a response: {response:?}"),
    }
}

