use std::time::{Duration, Instant};

use bytes::BytesMut;
use oxc_react_docgen_tsc_client::transport::{ContentLengthDecoder, DEFAULT_MAX_FRAME_BYTES};
use tokio_stream::StreamExt;
use tokio_util::codec::{Decoder, FramedRead};

#[test]
fn quantify_direct() {
    for mib in [16usize, 64, 128] {
        let mut dec = ContentLengthDecoder::new(DEFAULT_MAX_FRAME_BYTES);
        let mut buf = BytesMut::new();
        let chunk = vec![b'a'; 64 * 1024];
        let start = Instant::now();
        let mut calls = 0u64;
        while buf.len() < mib * 1024 * 1024 {
            buf.extend_from_slice(&chunk);
            let r = dec.decode(&mut buf).expect("no error expected");
            assert!(r.is_none());
            calls += 1;
        }
        eprintln!("DIRECT {mib} MiB no-terminator: buf.len={} calls={} elapsed={:?}", buf.len(), calls, start.elapsed());
    }
}

#[tokio::test(flavor = "multi_thread")]
async fn quantify_pipe() {
    // `yes` emits "y\n" forever — never `\r\n\r\n`.
    let mut child = tokio::process::Command::new("yes")
        .stdout(std::process::Stdio::piped())
        .kill_on_drop(true)
        .spawn()
        .expect("spawn yes");
    let stdout = child.stdout.take().expect("stdout");
    let mut framed = FramedRead::new(stdout, ContentLengthDecoder::new(DEFAULT_MAX_FRAME_BYTES));
    for secs in [1u64, 2, 4, 8] {
        let t = Instant::now();
        let r = tokio::time::timeout(Duration::from_secs(secs), framed.next()).await;
        assert!(r.is_err(), "decoder should still be waiting, got {r:?}");
        eprintln!(
            "PIPE after +{secs}s (elapsed {:?}): read_buffer.len={} cap={}",
            t.elapsed(),
            framed.read_buffer().len(),
            framed.read_buffer().capacity()
        );
    }
    let _ = child.start_kill();
}

