fn run(input: &[u8]) -> String {
    let mut dec = ContentLengthDecoder::new(DEFAULT_MAX_FRAME_BYTES);
    let mut buf = BytesMut::from(input);
    let mut out = Vec::new();
    loop {
        match dec.decode(&mut buf) {
            Ok(Some(f)) => out.push(String::from_utf8_lossy(&f).into_owned()),
            Ok(None) => break,
            Err(e) => {
                out.push(format!("ERR {e:?}"));
                // What a re-poll after error would see (FramedRead re-polled past its None).
                out.push(format!("leftover={:?}", String::from_utf8_lossy(&buf)));
                match dec.decode(&mut buf) {
                    r => out.push(format!("repoll={r:?}")),
                }
                break;
            }
        }
    }
    format!("{out:?}")
}

#[test]
fn quantify_parsing() {
    for (name, input) in [
        ("lowercase", &b"content-length: 2\r\n\r\nhi"[..]),
        ("nospace", b"Content-Length:2\r\n\r\nhi"),
        ("plus", b"Content-Length: +2\r\n\r\nhi"),
        ("dup", b"Content-Length: 5\r\nContent-Length: 2\r\n\r\nhiXYZ"),
        ("ctype-first", b"Content-Type: application/vscode-jsonrpc; charset=utf-8\r\nContent-Length: 2\r\n\r\nhi"),
        ("bad-then-valid", b"garbage\r\n\r\nContent-Length: 2\r\n\r\nhi"),
        ("bad-then-body-looks-like-header", b"garbage\r\n\r\nContent-Length: 30\r\n\r\nContent-Length: 2\r\n\r\nhi......"),
    ] {
        eprintln!("PARSE {name}: {}", run(input));
    }
}
