61	                out.push(format!("leftover={:?}", String::from_utf8_lossy(&buf)));
62	                match dec.decode(&mut buf) {
63	                    r => out.push(format!("repoll={r:?}")),
64	                }
65	                break;
66	            }
67	        }
68	    }
69	    format!("{out:?}")
70	}
